const e=[{id:"location",title:"독도의 위치와 영역",summary:"지도상의 위치와 영토·영해·영공",contentParagraphs:[[{text:"독도는 동해에 있으며 "},{id:"coordinates",text:"북위 37도, 동경 131도 부근",revealable:!0},{text:"에 자리한다. 울진군 죽변에서 동쪽으로 약 216.8km, 울릉도에서 "},{id:"ul-relation",text:"남동쪽으로 약 87.4km",revealable:!0},{text:" 떨어져 있다."}],[{text:"날씨가 맑으면 울릉도에서 독도를 "},{id:"visible-from-ul",text:"맨눈으로 볼 수 있다",revealable:!0},{text:". 두 섬 사이의 거리와 시야는 독도와 울릉도가 맺어 온 생활권 관계를 보여준다."}],[{text:"한 나라의 영역은 "},{id:"territorial-components",text:"영토·영해·영공",revealable:!0},{text:"으로 이루어진다. 영해는 영해 기선에서 최대 "},{id:"territorial-sea",text:"12해리(약 22km)",revealable:!0},{text:"까지이며, 섬 주변 바다의 경계와 배타적 경제 수역도 함께 살펴볼 주제다."}]],inquiryPrompt:"지도와 영역 개념을 함께 활용해 독도의 위치를 어떻게 설명할 수 있을까요?",checkQuestion:"독도의 위치를 지도에서 설명하는 데 가장 직접적인 근거는 무엇일까요?",checkOptions:[{id:"location-correct",label:"울릉도를 기준으로 한 방향과 거리",feedback:"맞아요. 기준점·방향·거리를 함께 보면 지도에서 위치 관계를 설명할 수 있습니다.",isCorrect:!0},{id:"location-weather",label:"독도 여행에 적합한 계절과 날씨",feedback:"여행 정보를 고르는 데 쓰이는 내용입니다. 위치를 설명하려면 지도상의 기준점과 방향, 거리를 확인하세요.",isCorrect:!1},{id:"location-color",label:"지도에 표시된 섬의 색깔",feedback:"색은 지도 표현 방식일 수 있습니다. 위치를 보여주는 기준점과 방향·거리 정보를 확인하세요.",isCorrect:!1}],sourceLabel:"초등 독도 바로 알기, 초등 3~4학년 독도 학습 자료"},{id:"landform",title:"독도의 지형",summary:"해저 화산에서 동도·서도와 해저 지형까지",contentParagraphs:[[{text:"독도는 약 "},{id:"formation-period",text:"460만~250만 년 전",revealable:!0},{text:" 해저 약 2,000m에서 분출한 용암이 굳어 형성된 화산섬이다. 울릉도와 제주도보다 먼저 만들어졌다."}],[{text:"처음에는 하나의 섬이었지만 파랑에 의한 "},{id:"erosion-separation",text:"침식으로 약 250만 년 전 동도와 서도로 나뉘었다",revealable:!0},{text:". 비바람과 파도에 깎이는 과정은 지금의 해안 절벽과 바위 지형을 만드는 데에도 영향을 주었다."}],[{text:"가파른 섬에는 주상절리와 해식동굴 등 화산·해안 지형이 나타난다. 바닷속에서는 울릉도와 독도 사이의 "},{id:"submarine-seamount",text:"안용복 해산",revealable:!0},{text:"을 비롯해 심흥택 해산과 이사부 해산 등 해저 화산 지형도 확인된다. 독도는 동도·서도와 89개의 작은 바위섬으로 이루어져 있다."}]],inquiryPrompt:"독도의 지형을 그림이나 굿즈로 표현한다면 어떤 섬이나 바위의 형태가 가장 잘 드러날까요?",checkQuestion:"독도의 섬과 바위 지형을 설명한 내용으로 알맞은 것은 무엇일까요?",checkOptions:[{id:"landform-correct",label:"동도와 서도, 89개의 작은 바위섬으로 이루어져 있다.",feedback:"맞아요. 두 큰 섬과 작은 바위섬이 독도의 기본적인 지형 구성을 이룹니다.",isCorrect:!0},{id:"landform-one",label:"하나의 둥근 섬과 모래사장으로 이루어져 있다.",feedback:"교재의 지형 설명과 다릅니다. 동도·서도와 작은 바위섬의 구성을 다시 떠올려보세요.",isCorrect:!1},{id:"landform-coral",label:"산호초가 쌓여 만들어진 평평한 섬이다.",feedback:"독도는 화산 활동으로 만들어진 돌섬으로 소개됩니다. 형성 과정과 섬의 형태를 다시 살펴보세요.",isCorrect:!1}],sourceLabel:"초등 독도 바로 알기, 초등 3~4학년 독도 학습 자료"},{id:"ecology",title:"독도의 생태계와 해양 자원",summary:"섬과 바다의 생물 다양성, 자원과 보전",contentParagraphs:[[{text:"급경사와 얕은 토양층, 적은 수분, 염분 섞인 강한 바람은 식물이 자라기 어려운 조건이다. 그럼에도 해국·번행초·섬기린초와 곰솔·동백나무 등이 자란다. 이처럼 "},{id:"island-habitat",text:"열악한 섬 환경에 적응한 생물",revealable:!0},{text:"이 독도 생태계의 특징이다."}],[{text:"괭이갈매기·슴새·바다제비를 포함해 교재의 조사 기록에는 약 "},{id:"bird-diversity",text:"139종의 조류",revealable:!0},{text:"가 기록되어 있으며, 이 세 종은 독도에서 번식한다. 무척추동물 약 370종과 해조류 약 223종, 오징어·꽁치·전복·해삼 등 주변 바다의 생물도 함께 살아간다. 독도는 천연기념물 제336호 독도천연보호구역으로 지정되어 있다."}],[{text:"수심 200m 아래의 "},{id:"deep-sea-water",text:"해양 심층수",revealable:!0},{text:"는 햇빛이 닿지 않고 수온이 낮은 바닷물이다. 해저에는 메탄을 주성분으로 하는 "},{id:"gas-hydrate",text:"가스 하이드레이트",revealable:!0},{text:"도 분포한다. 지질 경관과 생물 다양성은 자연유산의 가치로, 수산물과 해저 자원은 경제적 가치로 이어진다. 자원 이용 가능성은 생태계 보전과 채취 기술·비용을 함께 따져 살펴야 한다."}]],inquiryPrompt:"독도 주변 바다의 생물과 자원을 소개할 때 이용 가치와 보전의 필요성을 어떻게 함께 담을 수 있을까요?",checkQuestion:"독도 주변 해양 자원의 활용 가능성을 판단할 때 함께 고려할 점은 무엇일까요?",checkOptions:[{id:"ecology-correct",label:"생태계 영향과 채취 기술·비용을 함께 따져본다.",feedback:"맞아요. 자원의 존재뿐 아니라 지속 가능한 이용 조건도 함께 살펴야 합니다.",isCorrect:!0},{id:"ecology-unlimited",label:"자원이 확인되면 환경 영향과 관계없이 바로 채취한다.",feedback:"자원 개발은 생태계 보전과 기술·비용을 함께 고려해야 합니다.",isCorrect:!1},{id:"ecology-guaranteed",label:"해저에 자원이 있다는 사실만으로 실제 채취가 가능하다고 판단한다.",feedback:"자원의 존재와 실제 개발 가능성은 다릅니다. 채취 기술과 비용도 확인해야 합니다.",isCorrect:!1}],sourceLabel:"초등 독도 바로 알기, 초등 3~4학년 독도 학습 자료"},{id:"people",title:"주민의 삶과 섬의 관리",summary:"어민의 생업, 주민의 생활, 안전·관리 시설",contentParagraphs:[[{text:"과거 울릉도 어민과 해녀는 계절과 바다 날씨에 맞춰 독도를 찾아와 미역·전복을 채취하고 고기를 잡았다. 독도에서의 "},{id:"seasonal-livelihood",text:"어업과 해산물 채취",revealable:!0},{text:"는 울릉도와의 이동, 파도와 기상 조건에 영향을 받았다."}],[{text:"독도 주민 생활의 한 전환점은 "},{id:"first-resident",text:"1965년 울릉도 주민 최종덕의 입도",revealable:!0},{text:"다. 그는 1981년 주민등록을 옮겨 서도에 집을 짓고 생활했다. 현재 섬에는 주민 숙소와 선착장, 경비·등대 관리 시설이 있다."}],[{text:"샘물이 나는 "},{id:"watergol",text:"서도의 물골",revealable:!0},{text:"은 섬 생활과 이어져 있다. 주민뿐 아니라 경찰, 등대 관리원, 공무원 등 여러 사람이 섬에서 맡은 일을 한다. 바깥과의 이동이 배에 의존하는 섬에서는 "},{id:"island-living-conditions",text:"물·식량 공급과 안전, 시설 관리",revealable:!0},{text:"가 생활을 이어가는 중요한 조건이다."}]],inquiryPrompt:"독도에서 생활하는 사람들의 하루를 보여주는 상품 설명서에는 어떤 시설이나 역할을 담으면 좋을까요?",checkQuestion:"독도에서의 생활을 설명할 때 서로 연결해 살펴볼 내용은 무엇일까요?",checkOptions:[{id:"people-correct",label:"섬에 사는 사람들의 역할과 생활 시설, 물·이동·안전 문제",feedback:"맞아요. 사람과 시설, 섬에서 생활하기 위한 조건을 함께 살펴봐야 합니다.",isCorrect:!0},{id:"people-nature",label:"주민이나 관리 시설은 빼고 자연환경만",feedback:"자연환경뿐 아니라 주민과 여러 관리 인력, 생활 시설도 주제에 포함됩니다.",isCorrect:!1},{id:"people-tourism",label:"관광객이 방문하는 장소와 사진 명소만",feedback:"관광 정보만으로는 섬의 일상과 관리 역할을 설명하기 어렵습니다.",isCorrect:!1}],sourceLabel:"초등 3~4학년 독도에서 만나는 사람들 단원, 초등 독도 바로 알기"},{id:"history",title:"독도의 역사와 명칭",summary:"우산국·우산도부터 석도·독도까지 기록의 흐름",contentParagraphs:[[{text:"『삼국사기』에는 512년 신라 이사부가 "},{id:"usan-guk",text:"우산국을 복속한 일",revealable:!0},{text:"이 기록되어 있다. 1770년 『동국문헌비고』에는 울릉도와 우산이 우산국의 영역으로 함께 기록되어 있다. 고려와 조선 시대 문헌·지도에는 울릉도, 우산도, 무릉도 등 이름이 서로 다른 시기와 맥락에 나타난다."}],[{text:"1454년 『세종실록』 「지리지」에는 울릉도와 함께 "},{id:"usan-name",text:"우산도",revealable:!0},{text:"가 기록되어 있다. 조선 시대에는 울릉도 주민을 육지로 옮기는 쇄환 정책 뒤 관리가 섬을 살피는 수토가 시행되었다."}],[{text:"1900년 대한제국 칙령 제41호는 울도군 관할 섬으로 "},{id:"seokdo-name",text:"석도",revealable:!0},{text:"를 기록했다. 1906년 울릉군수 심흥택의 보고서에는 "},{id:"dokdo-name",text:"독도",revealable:!0},{text:"라는 표기가 나타난다. 이름의 변화는 기록의 연도·작성 주체·지명 사용 맥락을 함께 비교할 때 더 분명해진다."}]],inquiryPrompt:"이름이 다른 기록을 비교할 때 기록의 연도와 작성 배경을 함께 보면 무엇을 더 알 수 있을까요?",checkQuestion:"독도의 명칭과 역사 기록을 시간의 흐름에 따라 바르게 연결한 것은 무엇일까요?",checkOptions:[{id:"history-correct",label:"1454년 우산도 기록, 1900년 석도 기록, 1906년 독도 표기",feedback:"맞아요. 자료의 시기를 따라 이름과 기록의 변화를 정리할 수 있습니다.",isCorrect:!0},{id:"history-reverse",label:"1906년 우산도, 1900년 독도, 1454년 석도",feedback:"시대 순서와 맞지 않습니다. 각 이름이 어떤 연도의 기록에 나타나는지 다시 비교해보세요.",isCorrect:!1},{id:"history-no-date",label:"이름은 모두 같은 시기에 처음 사용되었다.",feedback:"이름은 여러 시대의 기록에 다르게 나타납니다. 연도를 함께 살펴보세요.",isCorrect:!1}],sourceLabel:"초등 독도 바로 알기 역사 단원"},{id:"conflict",title:"독도의 분쟁과 갈등",summary:"한·일 간 갈등의 전개와 시대별 문서 비교",contentParagraphs:[[{text:"에도 시대의 『은주시청합기』(1667), 돗토리번의 답변(1695), 막부의 도해 금지령(1696)은 울릉도 쟁계와 당시 일본의 섬 인식을 살펴보는 사료다. 1696년 막부는 "},{id:"japan-ban",text:"일본인의 울릉도 도해를 금지",revealable:!0},{text:"했다."}],[{text:"1877년 일본의 태정관 지령은 울릉도 외 한 섬(당시 일본에서 송도라 부른 독도)이 일본과 관계없다고 밝혔다. 반면 1905년 시마네현 고시 제40호는 독도를 일본에 편입한다고 공표했다. 같은 시기의 대한제국 칙령과 "},{id:"sim-report",text:"1906년 심흥택의 보고서",revealable:!0},{text:"도 함께 놓고 사건의 순서와 문서 작성 주체를 비교할 수 있다."}],[{text:"제2차 세계대전 이후 SCAPIN-677은 일본의 행정권이 미치는 범위에서 울릉도·독도·제주도를 제외했다. 1951년 샌프란시스코 강화 조약은 독도를 이름으로 직접 언급하지 않았고, 1952년 평화선 선언 뒤에는 1953년 독도조사단과 독도의용수비대, 1954년 등대 설치 등 관리 조치가 이어졌다. 각 문서는 작성 시기와 목적, 다루는 범위가 다르므로 "},{id:"document-context",text:"문서의 문맥과 표현을 서로 비교",revealable:!0},{text:"하며 갈등의 흐름을 살펴야 한다."}]],inquiryPrompt:"갈등의 흐름을 설명할 때 서로 다른 시기의 문서를 어떤 순서와 기준으로 비교하면 좋을까요?",checkQuestion:"독도를 둘러싼 역사적 갈등을 탐구하는 방법으로 가장 적절한 것은 무엇일까요?",checkOptions:[{id:"conflict-correct",label:"사건을 시간순으로 정리하고 문서의 작성 주체와 내용을 함께 비교한다.",feedback:"맞아요. 연표와 문서의 맥락을 함께 보면 갈등이 전개된 과정을 근거로 설명할 수 있습니다.",isCorrect:!0},{id:"conflict-one",label:"한 사건만 골라 앞뒤 맥락 없이 설명한다.",feedback:"사건의 배경과 이후 변화를 놓치기 쉽습니다. 시기별 사건과 문서를 함께 배열해보세요.",isCorrect:!1},{id:"conflict-slogan",label:"구호만으로 역사적 갈등을 설명한다.",feedback:"구호는 역사적 근거를 대신하지 못합니다. 사건의 순서와 관련 문서를 확인해보세요.",isCorrect:!1}],sourceLabel:"초등 독도 바로 알기 역사·독도를 지키기 위한 노력 단원"}],t={id:"3",topic:"독도",title:"독도를 배우고, AI로 배움의 가치를 디자인하다",description:"독도의 위치와 영역, 지형과 생태, 주민의 생활, 역사와 갈등을 배우고 생성형 AI로 굿즈와 상품 설명서를 만드는 모듈",steps:[{id:"step-1",title:"독도 주제 학습",description:"여섯 주제를 열어 독도의 위치·지형·생태·생활·역사를 살펴보세요.",content:"요약문에서 ‘클릭해서 내용 확인’을 눌러 중요한 사실을 펼쳐보세요. 디자인이나 상품 설명서에 활용하고 싶은 내용은 최대 3개까지 선택할 수 있습니다.",learningThemes:e,showResourceDropdown:!0,dropdownResources:[{id:"resource-1",label:"초등 3~4학년 독도 학습 자료",url:"https://contents.nahf.or.kr/eddokViewer/contens.do?viewType=Elementary34&levelId=eddok.d_0001"},{id:"resource-2",label:"초등 독도 학습 자료",url:"https://contents.nahf.or.kr/eddokViewer/contens.do?viewType=Elementary&levelId=eddok.d_0002"},{id:"resource-3",label:"중학교 독도 학습 자료",url:"https://contents.nahf.or.kr/eddokViewer/contens.do?viewType=Middle&levelId=eddok.d_0003"},{id:"resource-4",label:"고등학교 독도 학습 자료",url:"https://contents.nahf.or.kr/eddokViewer/contens.do?viewType=High&levelId=eddok.d_0004"}],editableContent:!1},{id:"step-2",title:"배운 내용 점검 퀴즈",description:"여섯 주제의 내용을 점검해보세요. 선택지 순서는 퀴즈를 새로 시작할 때마다 섞입니다.",content:"각 문항에서 가장 적절한 답을 고르고 해설을 확인하세요. 헷갈린 내용은 1단계의 해당 주제를 다시 읽어보세요.",learningThemes:e,useLearningQuiz:!0,editableContent:!1},{id:"step-3",title:"독도 굿즈 디자인 생성",description:"학습 내용을 입력하고 빈 목업과 Gemini용 디자인 프롬프트를 준비해보세요.",content:"1단계에서 결과물에 담아둔 핵심 내용은 입력칸에 미리 표시됩니다. 이를 바탕으로 티셔츠, 에코백, 핸드폰 케이스 디자인을 구상해보세요.",learningThemes:e,useGoodsDesignWorkspace:!0,editableContent:!1},{id:"step-4",title:"상품 설명서 제작",description:"굿즈의 의미와 사용 방법을 정리해 상품 설명서 이미지로 완성해보세요.",content:"1단계에서 골라둔 핵심 내용은 메시지 입력칸에 미리 표시됩니다. 굿즈 이미지와 함께 상품 설명서에 담을 내용을 다듬어보세요.",useProductSheetWorkspace:!0,editableContent:!1},{id:"step-5",title:"최종 작품 제출",description:"완성된 독도 굿즈와 상품 설명서를 공유하고 서로의 아이디어를 살펴보세요.",content:"독도 굿즈 디자인과 상품 설명서가 완성되었습니다. Padlet에 결과물을 업로드하고, 다른 학습자들이 어떤 독도의 가치와 메시지를 선택했는지 비교해보세요.",showEmbeddedPadlet:!0,padletUrl:"https://padlet.com/ghdwns00610/padlet-tzs4uog4dr84u5gi",editableContent:!1}]};export{e as DOKDO_LEARNING_THEMES,t as MODULE_3_DATA};
